{
  "headline": "FDA's records trace our supply to a plant classified OAI 18 days before the posting",
  "headline_cites": ["D19"],
  "sentences": [
    {
      "text": "FDA first posted the heparin sodium shortage on 2017-11-14 and it remains current as of 2026-10-21.",
      "cites": ["E91"]
    },
    {
      "text": "The shortage listing includes B. Braun Medical Inc., Baxter Healthcare, Fresenius Kabi USA, LLC, and Hospira, Inc., a Pfizer Company.",
      "cites": ["E87", "E88", "E89", "E90"]
    },
    {
      "text": "A Hospira, Inc. plant (FEI 1925262) on our labels was inspected and classified VAI on 2017-10-27, 18 days before the shortage posting.",
      "cites": ["D19", "E74"]
    },
    {
      "text": "That same plant received a Warning Letter on 2017-02-14, 273 days before the posting.",
      "cites": ["D18", "E78"]
    },
    {
      "text": "Baxter Healthcare plants on our labels have recent OAI classifications, including FEI 1025114 on 2024-02-09 and FEI 1416980 on 2026-04-02.",
      "cites": ["E24", "E31"]
    },
    {
      "text": "The rule-confirmed best option is to buy from BE Pharmaceuticals Inc., which is not on FDA's shortage list today.",
      "cites": ["D27"]
    }
  ]
}
